[data-workspace-area="conversation"] { background-color: var(--background) !important; background-image: linear-gradient(var(--ca-veil),var(--ca-veil)),var(--ca-clouds) !important; background-position: center !important; background-size: cover !important; background-repeat: no-repeat !important; }
.messages-timeline-scroll { background: transparent !important; }
[data-slot="sidebar"], [data-slot="sidebar-inner"] { background: var(--ca-side) !important; color: var(--ca-side-ink) !important; border-color: var(--ca-frame) !important; --foreground: var(--ca-side-ink); --muted-foreground: var(--ca-side-muted); }
[data-slot="sidebar"] { border-right: 1px solid var(--ca-frame) !important; box-shadow: 7px 0 18px -14px var(--ca-shade) !important; }
[data-slot="sidebar-inner"] { box-shadow: inset -1px 0 0 var(--ca-edge) !important; }
[data-slot="sidebar-inner"]::before { content: none !important; }
[data-thread-item] { border-radius: 7px !important; transition: background-color 150ms ease, box-shadow 150ms ease; }
[data-thread-item][aria-current="page"], [data-thread-item][data-state="active"] { box-shadow: inset 2px 0 0 var(--ca-accent); }
[data-slot="project-monogram"] { border-radius: 6px !important; box-shadow: 0 1px 2px var(--ca-shade); }
[data-chat-header] { background: var(--ca-header) !important; color: var(--ca-ink) !important; border-bottom: 1px solid var(--ca-line) !important; box-shadow: inset 0 1px 0 var(--ca-edge),0 4px 12px -7px var(--ca-shade) !important; }
[data-slot="composer-host"] { background: var(--ca-panel) !important; border: 1px solid var(--ca-line) !important; border-radius: 16px !important; box-shadow: inset 0 1px 0 var(--ca-edge),0 2px 3px var(--ca-shade),0 14px 32px -15px var(--ca-shade) !important; }
[data-chat-composer-form] { background: transparent !important; }
[data-slot="composer-host"]:focus-within { border-color: var(--ca-accent) !important; box-shadow: inset 0 1px 0 var(--ca-edge),0 0 0 2px var(--ca-rule),0 14px 32px -15px var(--ca-shade) !important; }
.composer-tiptap { color: var(--ca-ink) !important; }
[data-user-message-bubble] { color: var(--ca-ink) !important; background: var(--ca-panel) !important; border: 1px solid var(--ca-line) !important; border-radius: 16px 16px 5px 16px !important; box-shadow: inset 0 1px 0 var(--ca-edge),0 3px 9px -4px var(--ca-shade) !important; }
.chat-markdown { color: var(--ca-ink); line-height: 1.75; }
.chat-markdown :is(h1,h2) { font-family: Georgia,"Times New Roman",serif; font-weight: 500; letter-spacing: -.025em; color: var(--ca-ink); }
.chat-markdown h1 { font-size: 1.9em; }
.chat-markdown h2 { font-size: 1.45em; }
.chat-markdown a { color: var(--ca-accent); text-decoration-thickness: 1px; text-underline-offset: 4px; }
.chat-markdown blockquote { border-left: 2px solid var(--ca-accent); color: var(--ca-muted); }
.chat-markdown :not(pre) > code { background: var(--ca-code); border: 1px solid var(--ca-rule); border-radius: 4px; }
.chat-markdown-codeblock { background: var(--ca-code) !important; border: 1px solid var(--ca-line) !important; border-radius: 10px !important; box-shadow: inset 0 1px 0 var(--ca-edge) !important; }
[data-thread-details-card] { background: var(--ca-panel) !important; border: 1px solid var(--ca-line) !important; border-radius: 12px !important; box-shadow: 0 3px 10px -5px var(--ca-shade) !important; }
[data-settings-page-scroll] { background: var(--ca-side) !important; }
[data-thread-terminal-drawer] { border-top: 1px solid var(--ca-line) !important; box-shadow: 0 -5px 20px -10px var(--ca-shade) !important; }
[data-slot="button"] { border-radius: 7px; }
[data-slot="button"]:focus-visible, [data-slot="select-trigger"]:focus-visible { outline: 2px solid var(--ca-accent); outline-offset: 2px; }
[data-slot="input"], [data-slot="select-trigger"] { background: var(--ca-panel) !important; border-color: var(--ca-line) !important; border-radius: 7px !important; box-shadow: inset 0 1px 2px var(--ca-rule); }
[data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"] { background: var(--ca-raised) !important; color: var(--ca-ink) !important; border: 1px solid var(--ca-line) !important; border-radius: 12px !important; box-shadow: inset 0 1px 0 var(--ca-edge),0 16px 48px -12px var(--ca-shade) !important; }
[data-slot="tooltip-popup"] { border-radius: 5px !important; }
svg.lucide { stroke-width: 1.65; }
[data-slot="scroll-area-thumb"] { background: var(--ca-line) !important; border-radius: 8px !important; }
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-thumb { background: var(--ca-line); border-radius: 8px; }
::-webkit-scrollbar-track { background: transparent; }
@media (prefers-reduced-motion: reduce) { [data-thread-item] { transition: none; } }
